def handle(args, state, ds):
    report = ds.consistency_report()
    if report['pending'] == 0:
        return {'status': 'settled'}
    return {'status': 'pending', 'remaining': report['pending']}

def handle(args, state, ds):
    sync = ds.sync_status()
    if not sync['drift']:
        return {'status': 'in_sync'}
    return {'status': 'reconciling', 'detail': sync['detail']}

